for r in range(8):
 out=[]
 for c in range(8):
  pts=[]
  for y in range(r*80+2,r*80+10):
   for x in range(c*80+2,c*80+10): pts.append(im.getpixel((x,y)))
  bg=tuple(sorted(p[k] for p in pts)[len(pts)//2] for k in range(3))
  n=0; total=0
  for y in range(r*80+10,r*80+70):
   for x in range(c*80+10,c*80+70):
    p=im.getpixel((x,y)); d=sum((p[k]-bg[k])**2 for k in range(3))**0.5
    if d>22: n+=1
    total+=1
  out.append('%4.2f'%(n/total))
 print(' '.join(out))
